SELECT  FROM organization_invites i
WHERE i.organization_uuid = #{params.OrganizationUUID}
AND i.email ILIKE '%' || #{params.Query} || '%'
AND i.uuid > #{params.After}
ORDER BY i.uuid LIMIT #{params.Limit}

SELECT  FROM organization_invites i
